/// Blit an anti-aliased icon mask onto the target surface with color tint
pub fn render_icon_mask<const W: usize, const H: usize>(
    target: &mut Surface,
    x: i32,
    y: i32,
    mask: &[[u8; W]; H],
    tint_color: u32,
) {
    if !target.is_valid() || x + (W as i32) <= 0 || y + (H as i32) <= 0 {
        return;
    }
    let tint_a = (tint_color >> 24) & 0xFF;
    let tint_rgb = tint_color & 0x00FFFFFF;

    for row in 0..H {
        let py = y + row as i32;
        if py < 0 || py as usize >= target.height {
            continue;
        }
        for col in 0..W {
            let px = x + col as i32;
            if px < 0 || px as usize >= target.width {
                continue;
            }
            let cov = mask[row][col] as u32;
            if cov > 0 {
                let eff_alpha = (cov * tint_a) / 255;
                if eff_alpha > 0 {
                    let pixel = (eff_alpha << 24) | tint_rgb;
                    target.blend_pixel(px as usize, py as usize, pixel);
                }
            }
        }
    }
}

/// Draw the Purple mark at its native resolution.
pub fn render_purple_mark(dst: &mut Surface, x: i32, y: i32) {
    for (index, pixel) in PURPLE_MARK.chunks_exact(4).enumerate() {
        let px = x + (index % PURPLE_MARK_SIZE) as i32;
        let py = y + (index / PURPLE_MARK_SIZE) as i32;
        if px >= 0 && py >= 0 && pixel[3] != 0 {
            dst.blend_pixel(
                px as usize,
                py as usize,
                u32::from_be_bytes([pixel[3], pixel[0], pixel[1], pixel[2]]),
            );
        }
    }
}

#[repr(usize)]
#[derive(Clone, Copy)]
pub enum ShellIcon {
    Terminal,
    Files,
    Resources,
    Code,
    Settings,
    Wifi,
    Bluetooth,
    Power,
    Chevron,
    Restart,
}

pub fn shell_icon(dst: &mut Surface, icon: ShellIcon, x: i32, y: i32, size: usize, color: u32) {
    const EDGE: usize = 24;
    const MASK_SIZE: usize = EDGE * EDGE;
    const MASKS: &[u8; 10 * MASK_SIZE] = include_bytes!("../../assets/icons/shell-icons.alpha");
    let start = icon as usize * MASK_SIZE;
    for row in 0..size {
        for col in 0..size {
            let px = x + col as i32;
            let py = y + row as i32;
            if px >= 0 && py >= 0 {
                let mask = MASKS[start + (row * EDGE / size) * EDGE + col * EDGE / size];
                if mask != 0 {
                    dst.blend_pixel(
                        px as usize,
                        py as usize,
                        super::blend::scale_alpha(color, mask),
                    );
                }
            }
        }
    }
}
